<?php require 'includes/db.php';$r=$conn->query('SELECT id,name,category,price,image,badge FROM products WHERE stock>0 ORDER BY featured DESC,id DESC LIMIT 4');if(!$r||!$r->num_rows){echo '<p class="loading">New pieces are on their way. Check back soon.</p>';exit;}while($p=$r->fetch_assoc()):?><article class="product-card"><div class="product-img"><img loading="lazy" src="<?=e($p['image'])?>" alt="<?=e($p['name'])?>" onerror="this.onerror=null;this.src='assets/images/products/bag-default.svg';"><?php if($p['badge']):?><small><?=e($p['badge'])?></small><?php endif;?><button class="heart" type="button" aria-label="Add to wishlist" onclick="addWishlist(<?=$p['id']?>)"><i class="fa-regular fa-heart"></i></button><div class="product-actions"><a href="product.php?id=<?=$p['id']?>">VIEW DETAILS</a><button type="button" onclick="addCart(<?=$p['id']?>)">ADD TO BAG</button></div></div><div class="product-info"><span><?=e($p['category'])?></span><h3><?=e($p['name'])?></h3><strong><?=money($p['price'])?></strong></div></article><?php endwhile;?>
